arguments.command:
cat > tests/price_test.sh <<'E'
#!/bin/bash
fail=0
[ "$(bash bin/price 500)" = 450 ] || { echo "price 500"; fail=1; }
[ "$(bash bin/price 1000)" = 900 ] || { echo "price 1000"; fail=1; }
[ "$(bash bin/price 999)" = 899 ] || { echo "price 999"; fail=1; }
[ "$(bash bin/quote 999)" = "quote: 899" ] || { echo "quote 999"; fail=1; }
[ "$(bash lib/invoice.sh 999)" = "member total 899" ] || { echo "invoice 999"; fail=1; }
exit $fail
E
bash scripts/verify.sh; echo rc=$?
sed -i 's/\* 90 + 99) \/ 100/* 90) \/ 100/' bin/price bin/quote lib/invoice.sh
bash scripts/verify.sh; echo rc=$?; grep -rn "+ 99" bin lib | wc -l
mkdir notes; printf '# PRC-501\nbin/price, bin/quote, lib/invoice.sh all rounded up (+99). Removed the +99 in all three; added 999 cases to tests/price_test.sh.\n' > notes/PRC-501.md
git add -A; git commit -qm "PRC-501: round member price down in price, quote and invoice

Co-Authored-By: Claude Sonnet 5.5 <noreply@anthropic.com>"; git log --oneline | head -1

